 @Override public void onCreate(Bundle saved){super.onCreate(saved);try{modelId=OneModels.resolve(this,"signage",getIntent().getStringExtra("model_id"));OneModels.select(this,"signage",modelId);}catch(IllegalArgumentException e){Ui.error(this,"모델을 확인하세요",e);finish();return;}load();if(saved!=null){index=saved.getInt("index",index);playing=saved.getBoolean("playing",playing);videoPosition=saved.getInt("position",0);fullscreen=saved.getBoolean("fullscreen",false);}index=items.isEmpty()?0:Math.min(Math.max(0,index),items.size()-1);build();if(Build.VERSION.SDK_INT>=33)backCallback=Back33.register(this);incomingProcessed=saved!=null&&saved.getBoolean("shareProcessed",false);if(!receiveOneInput(getIntent()))receiveShare(getIntent());}
 private boolean receiveOneInput(Intent intent){
  if(incomingProcessed||intent==null)return false;Uri uri=intent.getData();if(uri==null||!OneImportPolicy.direct(uri.getScheme(),intent.getType(),intent.getBooleanExtra("one_input",false)))return false;
  if(OneImportPolicy.snapshot(uri.getAuthority(),getPackageName(),uri.getPath(),intent.getType())){playing=true;cancelLoad();ImportJob job=new ImportJob(getApplicationContext(),this,uri,intent.getFlags());importJob=job;try{job.future=io.submit(job);}catch(RejectedExecutionException e){importJob=null;Toast.makeText(this,"이미지를 다시 선택하세요",Toast.LENGTH_SHORT).show();}return true;}
  for(Item item:items)if(item.uri.equals(uri.toString())){incomingProcessed=true;index=items.indexOf(item);playing=true;persist();return true;}
  if(items.size()>=MAX_ITEMS)return false;String name="선택한 콘텐츠";try{DemoStore.Item demo=DemoStore.find(this,intent.getStringExtra("demo_id"));if(demo!=null)name=demo.title;}catch(Exception ignored){}
  items.add(new Item(uri.toString(),name,intent.getType()));index=items.size()-1;playing=true;incomingProcessed=true;persist();record("ONE_INPUT_ADDED");return true;
 }
